mapper.select:
SELECT id, ds_id, feedback_id, session_id, feedback_type, change_type, change_confidence,
       diff_summary, suggestions, review_task_ids, analyze_status, status, writeback_repo,
       wiki_writeback_flag, confidence_pushed, signal_keys, a_writeback_done, b_writeback_done,
       error_msg, retry_count, create_time, update_time
FROM fb_feedback_flow
WHERE ds_id = #{dsId}

    AND status IN

        #{st}



    AND feedback_type = #{feedbackType}


    AND change_type = #{changeType}


    AND session_id = #{sessionId}


    AND create_time >= #{startTime}


    AND create_time <= #{endTime}

ORDER BY create_time DESC

SELECT feedback_type AS group_key, COUNT(*) AS cnt
FROM fb_feedback_flow
WHERE ds_id = #{dsId}

    AND create_time >= #{startTime}


    AND create_time <= #{endTime}

GROUP BY feedback_type

SELECT status AS group_key, COUNT(*) AS cnt
FROM fb_feedback_flow
WHERE ds_id = #{dsId}

    AND create_time >= #{startTime}


    AND create_time <= #{endTime}

GROUP BY status
